examples.template:
MonarchMessageRow(
    MonarchMessageRowAuthor({{author}}),
    time: {{time|date}},
    now: {{now|date}},
    reactions: reactions,
    replyCount: {{replyCount}},
    onReactionToggle: { emoji, isOn in
        reactions = reactions.map { item in
            item.emoji == emoji
                ? MonarchReactionBarItem(emoji, count: item.count + (isOn ? 1 : -1), isReacted: isOn, label: item.label)
                : item
        }
    },
    onOpenThread: {}
) {
    Text({{body}})
} actions: {
    Button({{actions.0}}, systemImage: "pencil") {}
    Button({{actions.1}}, systemImage: "ellipsis") {}
}

